add_action( 'woocommerce_checkout_order_created', 'perfectpixel_save_order_weight' );
add_action( 'woocommerce_store_api_checkout_order_processed', 'perfectpixel_save_order_weight' );
add_action( 'woocommerce_admin_order_data_after_shipping_address', 'perfectpixel_show_order_weight' );

function perfectpixel_calculate_order_weight( $order ) {
	$weight = 0.0;
	foreach ( $order->get_items() as $item ) {
		$product = $item->get_product();
		if ( $product && ! $product->is_virtual() ) {
			$weight += (float) $product->get_weight() * (float) $item->get_quantity();
		}
	}
	return $weight;
}

function perfectpixel_save_order_weight( $order ) {
	$order->update_meta_data( '_perfectpixel_order_weight', perfectpixel_calculate_order_weight( $order ) );
	$order->save();
}

function perfectpixel_show_order_weight( $order ) {
	$weight = $order->get_meta( '_perfectpixel_order_weight' );
	if ( '' === $weight ) {
		$weight = perfectpixel_calculate_order_weight( $order );
	}
	if ( (float) $weight > 0 ) {
		echo '<p><strong>Συνολικό βάρος:</strong> ' . esc_html( wc_format_weight( $weight ) ) . '</p>';
	}
}
